import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.GbRRgL9t.js";const k=JSON.parse('{"title":"生产部署","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1789902237000}'),n={name:"getting-started/installation.md"};function p(d,a,l,o,h,c){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="生产部署" tabindex="-1">生产部署 <a class="header-anchor" href="#生产部署" aria-label="Permalink to &quot;生产部署&quot;">​</a></h1><p>本节介绍如何把 CircleChat 部署到生产服务器，支持 Nginx 反向代理、容器化运行，并说明更新服务器的步骤。</p><h2 id="反向代理-nginx" tabindex="-1">反向代理（Nginx） <a class="header-anchor" href="#反向代理-nginx" aria-label="Permalink to &quot;反向代理（Nginx）&quot;">​</a></h2><p>生产环境建议经 Nginx 反向代理并启用 HTTPS。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    server_name chat.example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    # 将请求转发到 Node 服务（默认端口 8090）</span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        proxy_pass http://127.0.0.1:8090;</span></span>
<span class="line"><span>        proxy_http_version 1.1;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        # WebSocket 升级必须透传以下两个头</span></span>
<span class="line"><span>        proxy_set_header Upgrade $http_upgrade;</span></span>
<span class="line"><span>        proxy_set_header Connection &quot;upgrade&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        proxy_set_header Host $host;</span></span>
<span class="line"><span>        proxy_set_header X-Real-IP $remote_addr;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p><strong>关键点</strong>：WebSocket 需要透传 <code>Upgrade</code> / <code>Connection</code> 两个头，否则实时消息无法推送。</p></blockquote><p>如果希望部署为「反代子路径」（例如 <code>https://chat.example.com/chat</code>），将 <code>location /chat</code> 转发到后端，并在 <a href="./configuration.html#显示--请求地址分离">配置</a> 中把 <code>apiBase</code> 设为 <code>/chat</code>。</p><h2 id="端口配置" tabindex="-1">端口配置 <a class="header-anchor" href="#端口配置" aria-label="Permalink to &quot;端口配置&quot;">​</a></h2><p>生产端口可通过环境变量覆盖：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">8080</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>容器部署时，容器端口映射到宿主机端口（详见下方「容器化」）。</p><h2 id="容器化运行-示例" tabindex="-1">容器化运行（示例） <a class="header-anchor" href="#容器化运行-示例" aria-label="Permalink to &quot;容器化运行（示例）&quot;">​</a></h2><p>项目使用 Nitro 的 <code>node-server</code> 预设构建，产物为纯 Node.js 进程，可直接封装进容器。</p><table tabindex="0"><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>基础镜像</td><td>Node.js（满足 ≥ 22.5，如 Node 25.9.0）</td></tr><tr><td>运行命令</td><td><code>node .output/server/index.mjs</code></td></tr><tr><td>容器端口</td><td><code>8080</code>（须与 <code>.env</code> 中 <code>PORT=8080</code> 一致）</td></tr><tr><td>端口映射</td><td>宿主端口 <code>5191 → 8080</code></td></tr><tr><td>工作目录</td><td><code>/home/CircleChat</code></td></tr><tr><td>裸仓库</td><td><code>/home/CircleChat.git</code>（用于拉取 / 部署 <code>main</code> 分支）</td></tr></tbody></table><blockquote><p>提示：容器内 <code>PORT</code> 必须与容器监听的端口一致，再把宿主端口映射到对外端口。</p></blockquote><h2 id="部署分支约定" tabindex="-1">部署分支约定 <a class="header-anchor" href="#部署分支约定" aria-label="Permalink to &quot;部署分支约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分支</th><th>用途</th></tr></thead><tbody><tr><td><code>main</code></td><td><strong>默认 / 稳定分支</strong>，用于发布；生产服务器从 <code>main</code> 拉取部署</td></tr><tr><td><code>dev</code></td><td>日常开发分支，功能完成后再合并回 <code>main</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 日常在 dev 上开发、提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 推送 dev</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 发布：把 dev 合入 main 并推送（服务器据此部署）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre></div><blockquote><p>远端名一般为 <code>CircleChat</code>（可用 <code>git remote -v</code> 查看）。</p></blockquote><h2 id="更新服务器" tabindex="-1">更新服务器 <a class="header-anchor" href="#更新服务器" aria-label="Permalink to &quot;更新服务器&quot;">​</a></h2><p>推送到 <code>main</code> 后，在部署机上按顺序执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 同步源码</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # 仅当 package.json / package-lock.json 有变动时需要</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 构建前端（Vite）与后端（Nitro）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重启服务进程 / 容器</span></span></code></pre></div><p>也可以用远端仓库的 <code>post-receive</code> 钩子把上面几步自动化——钩子同步源码后可继续执行 <code>npm install</code>（依赖有变动时）、<code>npm run build</code> 并重启服务。</p><h2 id="两个容易踩的坑" tabindex="-1">两个容易踩的坑 <a class="header-anchor" href="#两个容易踩的坑" aria-label="Permalink to &quot;两个容易踩的坑&quot;">​</a></h2><ol><li><strong>构建与运行版本一致</strong>：构建请用与服务运行时相同（或更高）的 Node 版本，<code>vite build</code> 需要 Node ≥ 20.19。</li><li><strong>依赖锁文件</strong>：旧版 npm（如 9.x）会在 <code>npm install</code> 时改写 <code>package-lock.json</code>（例如删掉 <code>libc</code> 字段），使部署机的 <code>git pull</code> 因工作区不干净而中止。建议升级 npm，或让部署目录只做 <code>git fetch</code> + <code>git reset --hard</code>（部署目录不应存在本地改动）。</li></ol><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>部署相关的环境变量与前端配置见<a href="./configuration.html">配置说明</a>。</p>`,27)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
